static ORIGINALS:OnceLock<Arc<tokio::sync::Semaphore>>=OnceLock::new();
#[derive(Debug,Clone,Copy,PartialEq,Eq)]enum Kind{Image,Video,File}
#[derive(Debug,Clone)]struct Item{message:Uuid,channel:Uuid,id:Uuid,name:String,kind:Kind,attachment:Option<Attachment>,embed:Option<Embed>}
impl Item{
    fn from_message(m:&Message)->Vec<Self>{
        let mut items=Vec::new();for a in m.attachments.iter().flatten(){
            if !matches!(a.moderation_status.as_deref(),None|Some("clean"|"failed"|"")){continue;}
            items.push(Self{message:m.id,channel:m.channel_id,id:a.id,name:a.original_file_name.clone(),kind:if a.mime_type.starts_with("image/"){Kind::Image}else if a.is_video(){Kind::Video}else{Kind::File},attachment:Some(a.clone()),embed:None});
        }
        for p in m.embeds.iter().flatten(){if p.animated_link()||p.has_video()||p.thumbnail.is_some()||p.image.is_some(){items.push(Self{message:m.id,channel:m.channel_id,id:p.id,name:p.title.clone().unwrap_or_else(||if p.animated_link(){"GIF".into()}else{crate::i18n::tr("Mídia").into()}),kind:if p.animated_link(){Kind::Image}else if p.has_video(){Kind::Video}else{Kind::Image},attachment:None,embed:Some(p.metadata())});}}
        items
    }
    fn endpoint(&self)->String{if self.attachment.is_some(){format!("/attachments/{}",self.id)}else if self.kind==Kind::Video||self.embed.as_ref().is_some_and(|e|e.has_video()){format!("/embeds/{}/video",self.id)}else{format!("/embeds/{}",self.id)}}
    fn cache_key(&self)->crate::media::disk::Key{use sha2::{Digest,Sha256};let revision=if let Some(a)=&self.attachment{serde_json::to_vec(&("gallery-v1",&a.mime_type,a.created_at,a.thumbnail_id,&a.moderation_status))}else{let p=self.embed.as_ref().unwrap();serde_json::to_vec(&("gallery-v1",p.version(),&p.thumbnail,&p.image))}.unwrap_or_default();crate::media::disk::Key{channel:self.channel,message:self.message,resource:self.id,revision:format!("{:x}",Sha256::digest(revision))}}
}
#[derive(Debug)]pub enum BrowserMsg{Select{message:Uuid,id:Uuid},Open,More,Filter,Close(Uuid),Loaded{token:Uuid,result:anyhow::Result<MediaPage>},Thumbnail{token:Uuid,message:Uuid,id:Uuid,result:Option<PreparedImage>},View(usize),ViewerClosed(Uuid),Ready{token:Uuid,result:anyhow::Result<Original>},Save,SaveTo{token:Uuid,path:std::path::PathBuf},Saved{token:Uuid,result:anyhow::Result<()>},Jump}
#[derive(Debug)]pub enum Original{Image(PreparedImage),Animation(PreparedAnimation),Video(Arc<TemporaryFile>)}
#[derive(Default)]pub(super) struct Browser{view:Option<View>,viewer:Option<Viewer>,job:Option<tokio::task::JoinHandle<()>>,thumbs:Vec<tokio::task::JoinHandle<()>>,items:Vec<Item>,pending:VecDeque<Item>,invalid:HashSet<Uuid>,cursor:MediaCursor,channel:Option<Uuid>,busy:bool}
struct View{token:Uuid,window:gtk::Window,grid:gtk::FlowBox,filter:gtk::DropDown,status:gtk::Label,more:gtk::Button,pictures:HashMap<(Uuid,Uuid),gtk::Picture>}
struct Viewer{token:Uuid,index:usize,downloadable:bool,window:gtk::Window,body:gtk::Box,status:gtk::Label,media:Option<gtk::MediaFile>,video:Option<gtk::Video>,file:Option<Arc<TemporaryFile>>,fullscreen:Option<std::rc::Rc<crate::ui::chat::video::Fullscreen>>,job:Option<tokio::task::JoinHandle<()>>,save_job:Option<tokio::task::JoinHandle<()>>}
impl Drop for Viewer{fn drop(&mut self){if let Some(job)=self.save_job.take(){job.abort();}if let Some(job)=self.job.take(){job.abort();}if let Some(media)=&self.media{media.set_muted(true);media.pause();}if let Some(full)=&self.fullscreen{full.shutdown();}if let Some(video)=&self.video{crate::ui::chat::transfers::detach_video(video.upcast_ref());video.set_media_stream(None::<&gtk::MediaStream>);}if let Some(media)=&self.media{media.clear();}self.window.set_child(None::<&gtk::Widget>);self.window.close();}}
impl Drop for Browser{fn drop(&mut self){self.clear();}}
impl Browser{fn clear(&mut self){if let Some(job)=self.job.take(){job.abort();}for job in self.thumbs.drain(..){job.abort();}self.viewer=None;if let Some(view)=self.view.take(){view.window.close();}self.items.clear();self.pending.clear();self.invalid.clear();self.cursor=Default::default();self.channel=None;self.busy=false;}}
