    pub(super) fn browser_access(&mut self){if let Some(channel)=self.browser.channel.filter(|c|!self.can_read_target(*c)){if let Some(cache)=self.connection.api.thumbnail_cache(self.current_user.id){cache.permit(channel,false);}self.browser.clear();}}
