fn v_status(browser:&Browser,text:&str){if let Some(v)=&browser.view{v.status.set_text(text);v.more.set_sensitive(!browser.busy);}}
fn browser_navigation(v:&mut Viewer,items:&[Item],sender:&ComponentSender<MainWindowModel>){let kind=items[v.index].kind;let previous=(0..v.index).rev().find(|i|items[*i].kind==kind);let next=(v.index+1..items.len()).find(|i|items[*i].kind==kind);let header=v.body.first_child().and_downcast::<adw::HeaderBar>().unwrap_or_else(||{let header=adw::HeaderBar::new();header.set_title_widget(Some(&adw::WindowTitle::new(v.window.title().as_deref().unwrap_or(""),"")));v.body.prepend(&header);header});for(label,msg,enabled)in [(crate::i18n::tr("Anterior"),BrowserMsg::View(previous.unwrap_or(v.index)),previous.is_some()),(crate::i18n::tr("Próxima"),BrowserMsg::View(next.unwrap_or(v.index)),next.is_some()),(crate::i18n::tr("Ir à mensagem"),BrowserMsg::Jump,true),(crate::i18n::tr("Baixar arquivo"),BrowserMsg::Save,true)]{if matches!(&msg,BrowserMsg::Save)&&!v.downloadable{continue;}let button=gtk::Button::with_label(label);button.set_sensitive(enabled);let input=sender.input_sender().clone();let target=if let BrowserMsg::View(index)=&msg{items.get(*index).map(|i|(i.message,i.id))}else{None};let jump=matches!(msg,BrowserMsg::Jump);button.connect_clicked(move |_|{let message=if let Some((message,id))=target{BrowserMsg::Select{message,id}}else if jump{BrowserMsg::Jump}else{BrowserMsg::Save};let _=input.send(MainWindowMsg::Browser(message));});if label==crate::i18n::tr("Anterior")||label==crate::i18n::tr("Próxima"){header.pack_start(&button);}else{header.pack_end(&button);}}}
fn escape(window:&gtk::Window){let keys=gtk::EventControllerKey::new();let weak=window.downgrade();keys.connect_key_pressed(move|_,key,_,_|{if key==gtk::gdk::Key::Escape{if let Some(w)=weak.upgrade(){w.close();}gtk::glib::Propagation::Stop}else{gtk::glib::Propagation::Proceed}});window.add_controller(keys);}
async fn thumbnail(api:&ApiClient,item:&Item,ticket:Option<&crate::media::disk::Ticket>)->Option<PreparedImage>{
    let bytes=if let Some(bytes)=match ticket{Some(t)=>t.get().await,None=>None}{Some(bytes)}else if item.attachment.is_some(){api.media_bytes(&format!("/attachments/{}/thumbnail",item.id),4<<20).await.ok()}else{use base64::Engine;api.get_embed(item.id).await.ok().and_then(|p|p.image_data).and_then(|data|base64::engine::general_purpose::STANDARD.decode(data.split_once(',').map_or(data.as_str(),|(_,d)|d)).ok())}?;
    tokio::task::spawn_blocking(move||PreparedImage::decode_thumbnail(&bytes,160,120)).await.ok().flatten()
}
async fn original(api:&ApiClient,item:&Item)->anyhow::Result<Original>{
    let permit=ORIGINALS.get_or_init(||Arc::new(tokio::sync::Semaphore::new(1))).clone().acquire_owned().await?;
    if item.attachment.is_none()&&item.kind==Kind::Image&&!item.embed.as_ref().is_some_and(|p|p.has_video()){
        use base64::Engine;let data=api.get_embed(item.id).await?.image_data.ok_or_else(||anyhow::anyhow!("Missing embed image"))?;let bytes=base64::engine::general_purpose::STANDARD.decode(data.split_once(',').map_or(data.as_str(),|(_,d)|d))?;
        return tokio::task::spawn_blocking(move||{let _permit=permit;if let Some(animation)=PreparedAnimation::decode(&bytes){Ok(Original::Animation(animation))}else{PreparedImage::decode_thumbnail(&bytes,4096,4096).map(Original::Image).ok_or_else(||anyhow::anyhow!("Invalid image"))}}).await?;
    }
    let file=api.download_temporary(&item.endpoint(),if item.kind==Kind::Image&&item.attachment.is_none(){8<<20}else{crate::api::features::MAX_FILE}).await?;
    if item.kind==Kind::Video{let path=file.0.clone();tokio::task::spawn_blocking(move||{let _permit=permit;crate::media::container::validate(&path)}).await??;return Ok(Original::Video(Arc::new(file)));}
    if item.embed.as_ref().is_some_and(|p|p.has_video()){return Ok(Original::Animation(PreparedAnimation::video(&file.0).await?));}
    tokio::task::spawn_blocking(move||{let _permit=permit;if let Ok(meta)=std::fs::metadata(&file.0){if meta.len()<=8<<20{if let Ok(bytes)=std::fs::read(&file.0){if let Some(animation)=PreparedAnimation::decode(&bytes){return Ok(Original::Animation(animation));}}}}PreparedImage::decode_viewer(&file.0).map(Original::Image).ok_or_else(||anyhow::anyhow!("Invalid image"))}).await?
}

