    {let mut state=backend.lock().unwrap();state.media_search=true;for i in 1..=24u128{let id=Uuid::from_u128(1000+i);let resource=Uuid::from_u128(2000+i);let kind=match i%3{0=>"application/pdf",1=>"image/png",_=>"video/webm"};state.paged_messages.push(serde_json::json!({"id":id,"channel_id":channel,"author_id":own.id,"created_at":at+chrono::Duration::seconds(i as i64),"attachments":[{"id":resource,"mime_type":kind,"original_file_name":if kind=="image/png"{"photo.png"}else{"file.bin"},"size_bytes":64,"thumbnail_width":64,"thumbnail_height":32,"created_at":at}]}));state.attachment_thumbnails.insert(format!("/attachments/{resource}/thumbnail"),png.clone());if kind=="image/png"{state.attachment_thumbnails.insert(format!("/attachments/{resource}"),png.clone());}}}
    let main=MainWindowModel::builder().launch(MainWindowInit{api_client:api,current_user:own}).detach();let window=adw::Window::builder().default_width(1100).default_height(760).content(main.widget()).build();window.present();main.emit(MainWindowMsg::StartLoading);until(context,||main.model().active_channel_id==Some(channel)&&main.model().can_read_target(channel));
    let start=backend.lock().unwrap().requests.len();main.emit(MainWindowMsg::Browser(BrowserMsg::Open));until(context,||main.model().browser.items.len()==8&&!main.model().browser.busy);
    let browser=main.model().browser.view.as_ref().unwrap().window.clone();let filter=main.model().browser.view.as_ref().unwrap().filter.clone();filter.set_selected(2);pump(context);assert_eq!(main.model().browser.view.as_ref().unwrap().pictures.len(),main.model().browser.items.iter().filter(|i|i.kind==Kind::File).count());filter.set_selected(0);pump(context);
    let image=main.model().browser.items.iter().position(|i|i.kind==Kind::Image).unwrap();main.emit(MainWindowMsg::Browser(BrowserMsg::View(image)));until(context,||main.model().browser.viewer.as_ref().is_some_and(|v|descendants(v.window.upcast_ref()).iter().any(|w|w.widget_name()=="image-viewer-picture")));
    let viewer=main.model().browser.viewer.as_ref().unwrap().window.clone();let token=main.model().browser.viewer.as_ref().unwrap().token;find_button(viewer.upcast_ref(),"Próxima").emit_clicked();until(context,||main.model().browser.viewer.as_ref().is_some_and(|v|v.token!=token));assert_eq!(main.model().browser.items[main.model().browser.viewer.as_ref().unwrap().index].kind,Kind::Image);
    main.emit(MainWindowMsg::Browser(BrowserMsg::More));until(context,||main.model().browser.items.len()>8&&!main.model().browser.busy);let selected=main.model().browser.items[image].message;{main.state().get_mut().model.browser_invalidate(selected);}assert!(!main.model().browser.items.iter().any(|i|i.message==selected));assert!(main.model().browser.viewer.is_none());
    let requests=backend.lock().unwrap().requests[start..].to_vec();assert!(requests.iter().any(|(m,p,b)|m=="POST"&&p=="/search"&&b["contains_attachment"]==true));assert!(requests.iter().filter(|(_,p,_)|p.contains("/messages?")&&reqwest::Url::parse(&format!("http://local{p}")).unwrap().query_pairs().any(|(k,v)|k=="limit"&&v=="1")).count()>=8,"browser results use bounded one-message lookups alongside independent chat refreshes");
    {let mut model=main.state().get_mut();model.model.access.remove(&channel);model.model.browser_access();}assert!(!browser.is_visible());assert!(main.model().browser.view.is_none());window.set_content(None::<&gtk::Widget>);window.close();drop(main);server.abort();pump(context);
